use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn generate_monster_mappings (compressor : & MonsterCompressor , output_file : & str) -> Result < () > { let mut output = String :: new () ; output . push_str ("# Monster Group Order Compression Mappings\n") ; output . push_str ("# Order: 808,017,424,794,512,875,886,459,904,961,710,757,005,754,368,000,000,000\n") ; output . push_str ("# Factorization: 2^46 × 3^20 × 5^9 × 7^6 × 11^2 × 13^3 × 17 × 19 × 23 × 29 × 31 × 41 × 47 × 59 × 71\n\n") ; output . push_str ("## 2^46 - Pair Mappings (46 most common)\n") ; for (pair , emoji) in & compressor . pair_emojis { let freq = compressor . pair_frequencies . get (pair) . unwrap_or (& 0) ; output . push_str (& format ! ("{} {} (freq: {})\n" , emoji , pair , freq)) ; } output . push_str ("\n## 3^20 - Triple Mappings (20 samples)\n") ; for (triple , emoji) in & compressor . triple_emojis { let freq = compressor . triple_frequencies . get (triple) . unwrap_or (& 0) ; output . push_str (& format ! ("{} {} (freq: {})\n" , emoji , triple , freq)) ; } output . push_str ("\n## 5^9 - 5-gram Mappings (9 samples)\n") ; for (penta , emoji) in & compressor . penta_emojis { let freq = compressor . penta_frequencies . get (penta) . unwrap_or (& 0) ; output . push_str (& format ! ("{} {} (freq: {})\n" , emoji , penta , freq)) ; } output . push_str ("\n## 7^6 - 7-gram Mappings (6 samples)\n") ; for (hepta , emoji) in & compressor . hepta_emojis { let freq = compressor . hepta_frequencies . get (hepta) . unwrap_or (& 0) ; output . push_str (& format ! ("{} {} (freq: {})\n" , emoji , hepta , freq)) ; } fs :: write (output_file , output) ? ; println ! ("👹 Monster Group mappings written to {}" , output_file) ; Ok (()) }
}